         var remove=new List<int>();foreach(var k in receipts.Keys)if(!sequences.Contains(k))remove.Add(k);foreach(int k in remove)receipts.Remove(k);}
        public LocalAgentOrder OrderAt(int index)=>orders[index];
        public void ClearTeam(int team)
