            if(disposed)return;if(pending!=null && pending.receipt.Team==team){pending.receipt.Status=LocalOrderStatus.Invalidated;pending.receipt.Error="Superseded by a whole-army command.";pending=null;}
            var next=(LocalAgentOrder[])orders.Clone();bool changed=false;for(int i=0;i<next.Length;i++)if(teams[i]==team && next[i].slotPlusOne!=0){next[i]=default;changed=true;}
