    public sealed class LocalOrdersSceneTests
    {
        private Scene scene;private MassEngineManager m;private WarSandboxBattleController c;private float oldDelta;private bool initialized;private string output;
        private IEnumerator Frames(int n){for(int i=0;i<n;i++)yield return null;}
        [UnitySetUp] public IEnumerator Setup()
        {
            var arg=Environment.GetCommandLineArgs().FirstOrDefault(x=>x.StartsWith("--interaction-p6-output="));if(arg==null)Assert.Ignore("P6 owned opt-in required");output=arg.Substring("--interaction-p6-output=".Length);
            oldDelta=Time.captureDeltaTime;initialized=true;Time.captureDeltaTime=1f/60;
            Assert.IsNull(WarSandboxSceneSession.Instance);yield return SceneManager.LoadSceneAsync("Assets/Game/Scenes/Green.unity",LoadSceneMode.Additive);scene=SceneManager.GetSceneByPath("Assets/Game/Scenes/Green.unity");yield return Frames(3);
            m=WarSandboxSceneSession.FindManager(scene,out _);c=WarSandboxRuntimeBootstrap.EnsureControls(m);c.RebuildArmyStates();Assert.IsTrue(c.IssueOrder(ArmyOrder.Hold(0)));Assert.IsTrue(c.IssueOrder(ArmyOrder.Hold(1)));yield return Frames(20);
        }
        [UnityTearDown] public IEnumerator Cleanup(){if(!initialized)yield break;if(m!=null)m.DisableLocalOrderPrototype();if(scene.IsValid()&&scene.isLoaded)yield return SceneManager.UnloadSceneAsync(scene);Time.captureDeltaTime=oldDelta;Time.timeScale=1;yield return null;}
        private IEnumerator Wait(LocalOrderReceipt r){for(int i=0;i<600&&r.Status==LocalOrderStatus.AwaitingSnapshot;i++)yield return null;Assert.AreEqual(LocalOrderStatus.Committed,r.Status,r.Error);}
        [UnityTest] public IEnumerator P6GreenBridgeWholeArmyResetAndResourceBudget()
        {
            Assert.AreEqual(2048,m.Buffers.AgentCount);Assert.IsNull(m.LocalOrders);Assert.IsTrue(m.TryEnableLocalOrderPrototype(out var error),error);var local=m.LocalOrders;int epoch=local.Epoch;
            var r=local.Submit(epoch,0,1,Enumerable.Range(0,32).ToArray(),LocalOrderKind.Hold,Vector2.zero);yield return Wait(r);yield return Frames(35);Assert.Greater(r.GpuExecutingMembers,0);
            Assert.IsTrue(c.IssueOrder(ArmyOrder.Hold(0)));Assert.AreEqual(0,local.ActiveGroups);Assert.AreEqual(0,local.ActiveMembers);
            var pending=local.Submit(epoch,0,2,new[]{0},LocalOrderKind.Hold,Vector2.zero);m.ResetScenario();Assert.AreEqual(LocalOrderStatus.Invalidated,pending.Status);Assert.IsNull(m.LocalOrders);Assert.AreEqual(0,local.GpuBytes);
            Assert.IsTrue(m.TryEnableLocalOrderPrototype(out error),error);Assert.AreNotEqual(epoch,m.LocalOrders.Epoch);Assert.AreEqual(LocalOrderStatus.Rejected,m.LocalOrders.Submit(epoch,0,3,new[]{0},LocalOrderKind.Hold,Vector2.zero).Status);
            string text="2048 Green;FlowCellCount="+m.Buffers.FlowCellCount+";groups=4+1 staging;GPU bytes="+m.LocalOrders.GpuBytes+";first plan worker ms="+r.PlanMilliseconds+";snapshot ms="+r.ReadbackMilliseconds+";upload ms="+r.UploadMilliseconds+";CPU cache upper bytes="+local.NavigationCpuUpperEstimate+";whole-army clears;reset invalidates;new epoch rejects old";
            File.WriteAllText(Path.Combine(output,"p6-green-resources.txt"),text);Debug.Log(text);
        }
        [Serializable] private sealed class TimingRow {public string mode;public double medianMs,p95Ms,meanMs;public int frames;public long localGpuBytes;}
        [Serializable] private sealed class TimingReport {public string method="Coroutine wall intervals, rendered batch scene, 5s windows after 2s warmup; not present FPS or GPU timing. Fixed simulation delta. Short ABBA diagnostic, not performance acceptance.";public List<TimingRow> rows=new List<TimingRow>();}
        [UnityTest] public IEnumerator P6DisabledAndEmptyChannelShortABBAIntervals()
        {
            var report=new TimingReport();foreach(string mode in new[]{"disabled","enabled-empty","enabled-empty","disabled"})
            {
                if(mode=="disabled")m.DisableLocalOrderPrototype();else Assert.IsTrue(m.TryEnableLocalOrderPrototype(out var error),error);
                double warm=Time.realtimeSinceStartupAsDouble+2;while(Time.realtimeSinceStartupAsDouble<warm)yield return null;
                var samples=new List<double>();double begin=Time.realtimeSinceStartupAsDouble,previous=begin;
                while(Time.realtimeSinceStartupAsDouble-begin<5){yield return null;double now=Time.realtimeSinceStartupAsDouble;samples.Add((now-previous)*1000);previous=now;}
                samples.Sort();report.rows.Add(new TimingRow{mode=mode,frames=samples.Count,medianMs=samples[samples.Count/2],p95Ms=samples[(int)((samples.Count-1)*.95)],meanMs=samples.Average(),localGpuBytes=m.LocalOrders?.GpuBytes??0});
            }
            File.WriteAllText(Path.Combine(output,"p6-short-intervals.json"),JsonUtility.ToJson(report,true));
        }
